#include <Arduino.h>
const int rgb1R = 2; 
const int rgb1G = 3; 
const int rgb1B = 4;  
const int rgb2R = 5;
const int rgb2G = 6;
const int rgb2B = 7;
const int rgb3R = 8;
const int rgb3G = 9;
const int rgb3B = 10;

void setup();
void setLED1Color(int r, int g, int b);
void setLED2Color(int r, int g, int b);
void setLED3Color(int r, int g, int b);
void loop();
void setup() {
  pinMode(rgb1R, OUTPUT);
  pinMode(rgb1G, OUTPUT);
  pinMode(rgb1B, OUTPUT);
  pinMode(rgb2R, OUTPUT);
  pinMode(rgb2G, OUTPUT);
  pinMode(rgb2B, OUTPUT);
  pinMode(rgb3R, OUTPUT);
  pinMode(rgb3G, OUTPUT);
  pinMode(rgb3B, OUTPUT);
}
void setLED1Color(int r, int g, int b) {
  digitalWrite(rgb1R, r);
  digitalWrite(rgb1G, g);
  digitalWrite(rgb1B, b);
}
void setLED2Color(int r, int g, int b) {
  digitalWrite(rgb2R, r);
  digitalWrite(rgb2G, g);
  digitalWrite(rgb2B, b);
}
void setLED3Color(int r, int g, int b) {
  digitalWrite(rgb3R, r);
  digitalWrite(rgb3G, g);
  digitalWrite(rgb3B, b);
}
void loop() {
  setLED1Color(HIGH, LOW, LOW);  
  setLED2Color(LOW, LOW, HIGH);  
  setLED3Color(LOW, HIGH, LOW);  
  delay(2000);
  setLED1Color(LOW, HIGH, LOW);  
  setLED2Color(HIGH, LOW, LOW);  
  setLED3Color(LOW, LOW, HIGH);  
  delay(2000);
  setLED1Color(LOW, LOW, HIGH);  
  setLED2Color(LOW, HIGH, LOW);  
  setLED3Color(HIGH, LOW, LOW);  
  delay(2000);
}
